head.b:skin:
/* 
THEME: TOEFL Mastery (Academic Slate & Ivory)
SYSTEM: Standardized English Assessment Framework
*/
:root {
    --ets-blue: #004a99;
    --academic-gray: #475569;
    --paper-ivory: #fcfcf9;
    --border-slate: #cbd5e1;
    --success-green: #10b981;
}
body {
    background-color: #f1f5f9;
    color: #1e293b;
    font-family: 'Georgia', serif; /* Classic Academic Font */
    margin: 0; padding: 0;
}
.header-wrap {
    background: var(--ets-blue);
    color: white;
    padding: 50px 20px;
    text-align: center;
    border-bottom: 5px solid #003366;
}
.header-wrap h1 { 
    font-family: 'Inter', sans-serif;
    font-size: 28px; 
    font-weight: 800; 
    text-transform: uppercase; 
    letter-spacing: 2px;
    margin: 0;
}
.main-container {
    max-width: 850px;
    margin: -30px auto 60px;
    padding: 20px;
}
.exam-card {
    background: var(--paper-ivory);
    border-radius: 8px;
    padding: 40px;
    border: 1px solid var(--border-slate);
    box-shadow: 0 10px 25px rgba(0,0,0,0.05);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-family: 'Inter', sans-serif;
    font-weight: 700;
    margin-bottom: 8px;
    color: var(--ets-blue);
    font-size: 12px;
    text-transform: uppercase;
}
.input-group input, .input-group textarea, .input-group select {
    width: 100%;
    padding: 14px;
    border: 1px solid var(--border-slate);
    border-radius: 4px;
    font-family: 'Georgia', serif;
    box-sizing: border-box;
    background: #fff;
    font-size: 15px;
}
.input-group select { cursor: pointer; border-left: 4px solid var(--ets-blue); }

.flex-row { display: flex; gap: 20px; flex-wrap: wrap; }
.flex-item { flex: 1; min-width: 250px; }

h2 { font-family: 'Inter', sans-serif; font-weight: 800; font-size: 18px; margin-bottom: 25px; color: var(--academic-gray); }

.copy-btn {
    background: var(--ets-blue);
    color: white;
    border: none;
    padding: 18px;
    cursor: pointer;
    font-family: 'Inter', sans-serif;
    font-weight: 700;
    width: 100%;
    border-radius: 4px;
    transition: 0.2s;
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.copy-btn:hover { background: #003366; }
footer { text-align: center; color: #94a3b8; padding: 40px; font-size: 11px; font-family: 'Inter', sans-serif; }

body.script:
function copyPrompt() {
    var topic = document.getElementById("inputTopic").value || "General Academic Topic";
    var notes = document.getElementById("inputNotes").value || "Focus on academic vocabulary and natural flow.";
    var section = document.getElementById("inputSection").value;
    var level = document.getElementById("inputLevel").value;

    var template = document.getElementById("templateID").innerText;

    var finalPrompt = template
        .replace("[USER_TOPIC]", topic)
        .replace("[USER_NOTES]", notes)
        .replace(/\[USER_SECTION\]/g, section)
        .replace(/\[USER_LEVEL\]/g, level);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("📝 TOEFL Assessment Prompt Copied! [Section: " + section.split(':')[0] + "]");
}
